  display: block;
}

.cms-shell {
  padding: 24px;
  max-width: 1600px;
  margin: 0 auto;
  color: #16324a;
}

.cms-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.cms-header h1 {
  margin: 2px 0 6px;
  font-size: 30px;
}

.cms-header p {
  margin: 0;
  color: #617386;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 12px;
  font-weight: 700;
  color: #167f8e !important;
}

.header-actions, .editor-actions, .json-actions, .editor-footer {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}

button {
  border: 0;
  border-radius: 9px;
  padding: 10px 14px;
  cursor: pointer;
  font-weight: 650;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.primary {
  background: #167f8e;
  color: #fff;
}

.secondary {
  background: #eef3f6;
  color: #25445e;
  border: 1px solid #d6e0e6;
}

.dirty-badge, .language-chip {
  border-radius: 999px;
  padding: 5px 9px;
  background: #fff3cd;
  color: #7a5a00;
  font-size: 12px;
  font-weight: 700;
}

.status {
  padding: 12px 14px;
  border-radius: 9px;
  margin-bottom: 14px;
}

.status.success {
  background: #eaf7ee;
  color: #216b39;
}

.status.error {
  background: #fdecec;
  color: #9a2c2c;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.metrics article {
  border: 1px solid #dbe4ea;
  border-radius: 12px;
  padding: 14px;
  background: #fff;
  display: flex;
  flex-direction: column;
}

.metrics strong {
  font-size: 25px;
}

.metrics span {
  color: #6b7c8b;
  font-size: 13px;
}

.cms-layout {
  display: grid;
  grid-template-columns: 270px minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.section-nav {
  border: 1px solid #dbe4ea;
  border-radius: 12px;
  background: #fff;
  overflow: hidden;
  position: sticky;
  top: 12px;
  max-height: calc(100vh - 30px);
  overflow-y: auto;
}

.nav-title {
  padding: 15px;
  border-bottom: 1px solid #e5ebef;
  display: flex;
  flex-direction: column;
}

.nav-title small {
  color: #778895;
  margin-top: 3px;
}

.section-nav button {
  width: 100%;
  border-radius: 0;
  background: #fff;
  text-align: left;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  border-bottom: 1px solid #edf1f4;
  padding: 12px 14px;
}

.section-nav button:hover, .section-nav button.active {
  background: #eaf5f6;
}

.section-nav button.active {
  box-shadow: inset 4px 0 #167f8e;
}

.section-name {
  overflow: hidden;
  text-overflow: ellipsis;
}

.section-meta {
  color: #7c8b96;
  font-size: 12px;
  white-space: nowrap;
}

.editor {
  min-width: 0;
  border: 1px solid #dbe4ea;
  border-radius: 12px;
  background: #fff;
  overflow: hidden;
}

.editor-title {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 18px;
  border-bottom: 1px solid #e4eaee;
}

.editor-title h2 {
  margin: 3px 0 0;
}

.path {
  margin: 0;
  color: #7a8994;
  font-size: 13px;
}

.toolbar {
  padding: 14px 18px;
  background: #f8fafb;
  border-bottom: 1px solid #e5ebef;
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 190px auto;
  gap: 12px;
  align-items: end;
}

.toolbar label, .field-value {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.toolbar label > span {
  font-size: 12px;
  color: #647786;
  font-weight: 650;
}

.toolbar input, .toolbar select, .field-value input, .field-value textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #ccd8df;
  border-radius: 8px;
  padding: 10px 11px;
  font: inherit;
  color: inherit;
  background: #fff;
}

.checkbox {
  flex-direction: row !important;
  align-items: center;
  padding-bottom: 9px;
}

.checkbox input {
  width: auto !important;
}

.fields-table {
  width: 100%;
}

.field-row {
  display: grid;
  grid-template-columns: minmax(220px, 35%) minmax(260px, 1fr) 38px;
  gap: 14px;
  align-items: start;
  padding: 13px 18px;
  border-bottom: 1px solid #edf1f4;
}

.field-row:hover {
  background: #fbfcfd;
}

.field-key {
  min-width: 0;
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 5px 8px;
}

.field-key strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.field-key code {
  grid-column: 1/-1;
  color: #768691;
  white-space: normal;
  overflow-wrap: anywhere;
  font-size: 12px;
}

.language-chip {
  justify-self: start;
  background: #eaf5f6;
  color: #16717d;
  padding: 3px 7px;
}

.field-value textarea {
  resize: vertical;
}

.boolean-control {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  padding-top: 9px;
}

.boolean-control input {
  width: auto;
}

.delete {
  width: 34px;
  height: 34px;
  padding: 0;
  border-radius: 50%;
  background: #fff0f0;
  color: #a52c2c;
  font-size: 20px;
}

.json-panel {
  padding: 18px;
}

.json-panel p {
  color: #647786;
}

.json-panel textarea {
  box-sizing: border-box;
  width: 100%;
  min-height: 600px;
  border: 1px solid #ccd8df;
  border-radius: 9px;
  padding: 14px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
}

.editor-footer {
  justify-content: flex-end;
  padding: 16px 18px;
  background: #f8fafb;
  border-top: 1px solid #e5ebef;
}

.loading, .empty-state, .empty-nav {
  padding: 30px;
  text-align: center;
  color: #71828e;
}

@media (max-width: 1000px) {
  .metrics {
    grid-template-columns: repeat(2, 1fr);
  }
  .cms-layout {
    grid-template-columns: 1fr;
  }
  .section-nav {
    position: static;
    max-height: 300px;
  }
  .toolbar {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 700px) {
  .cms-shell {
    padding: 12px;
  }
  .cms-header, .editor-title {
    flex-direction: column;
  }
  .metrics {
    grid-template-columns: 1fr 1fr;
  }
  .toolbar {
    grid-template-columns: 1fr;
  }
  .field-row {
    grid-template-columns: 1fr 38px;
  }
  .field-key {
    grid-column: 1/-1;
  }
  .field-value {
    grid-column: 1;
  }
  .delete {
    grid-column: 2;
    grid-row: 2;
  }
}
.source-selector {
  display: flex;
  align-items: flex-end;
  gap: 16px;
  flex-wrap: wrap;
  margin: 16px 0;
  padding: 16px;
  border: 1px solid #d9e2ec;
  border-radius: 14px;
  background: #fff;
}

.source-selector label {
  display: grid;
  gap: 6px;
  min-width: 280px;
}

.source-selector select {
  min-height: 42px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  padding: 0 12px;
  background: #fff;
}

.source-selector small {
  color: #64748b;
  padding-bottom: 10px;
