  width: min(1120px, 100% - 2rem);
  margin: 0 auto;
}

.narrow {
  max-width: 760px;
}

.page-hero, .section {
  padding: 4rem 0;
}

.page-hero {
  background: linear-gradient(180deg, #e8f4f7 0%, #fbf8f2 100%);
}

.eyebrow {
  color: #0b6e8f;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

h1, h2 {
  color: #08263a;
}

.pricing-card {
  background: #fff;
  border-radius: 24px;
  padding: 1.5rem;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.06);
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

label {
  display: grid;
  gap: 0.4rem;
  color: #334155;
  font-weight: 700;
}

input {
  border: 1px solid #cbd5e1;
  border-radius: 14px;
  padding: 0.85rem 1rem;
  font: inherit;
}

.repeat-row {
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr 0.8fr auto;
  gap: 0.7rem;
  margin: 0.75rem 0;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 0.85rem 1rem;
  font-weight: 800;
  cursor: pointer;
}

.btn-primary {
  background: #f28c28;
  color: #fff;
}

.btn-secondary {
  background: #e8f4f7;
  color: #08263a;
}

.btn-danger {
  background: #9f1d1d;
  color: #fff;
}

.actions {
  margin-top: 1.5rem;
}

.success {
  color: #047857;
  font-weight: 800;
}

.error-message {
  color: #9f1d1d;
  font-weight: 800;
}

@media (max-width: 820px) {
  .field-grid, .repeat-row {
    grid-template-columns: 1fr;
  }
