  padding-top: 2rem;
  padding-bottom: 4rem;
  color: #253746;
}

.page-heading {
  display: flex;
  justify-content: space-between;
  gap: 1.5rem;
  align-items: flex-start;
  margin-bottom: 1.5rem;
}

.page-heading h1 {
  margin: 0.2rem 0 0.5rem;
}

.page-heading p {
  max-width: 760px;
  margin: 0;
  color: #60717e;
}

.eyebrow {
  color: #b47c35 !important;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
  font-size: 0.78rem;
}

.refresh-button, .calendar-toolbar button {
  border: 1px solid #d7c9b5;
  background: #fff;
  border-radius: 10px;
  padding: 0.65rem 1rem;
  cursor: pointer;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin: 1.25rem 0;
}

.summary-grid article {
  border: 1px solid #e6ded2;
  border-radius: 14px;
  padding: 1rem;
  background: #fbf8f2;
}

.summary-grid span {
  display: block;
  color: #6d7880;
  font-size: 0.9rem;
}

.summary-grid strong {
  display: block;
  font-size: 1.8rem;
  margin-top: 0.2rem;
}

.calendar-toolbar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  margin: 1.5rem 0 0.75rem;
}

.calendar-toolbar > div {
  min-width: 230px;
  text-align: center;
}

.calendar-toolbar h2 {
  margin: 0;
  text-transform: capitalize;
}

.today-link {
  border: 0 !important;
  padding: 0.2rem !important;
  color: #8f642d;
  background: transparent !important;
}

.cancelled-toggle {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  justify-content: flex-end;
  margin-bottom: 0.75rem;
  font-size: 0.9rem;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin: 0.75rem 0;
  color: #5f6c75;
  font-size: 0.85rem;
}

.legend span {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.legend i {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  display: inline-block;
}

.legend .past, .event.past {
  background: #e6ded2;
}

.legend .today, .event.today {
  background: #f4d38a;
}

.legend .future, .event.future {
  background: #d8eee1;
}

.legend .cancelled, .event.cancelled {
  background: #f0d7d7;
}

.calendar-shell {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  border-top: 1px solid #ded7cc;
  border-left: 1px solid #ded7cc;
  transition: opacity 0.2s;
}

.calendar-shell.loading {
  opacity: 0.55;
}

.weekday {
  padding: 0.65rem 0.35rem;
  text-align: center;
  font-weight: 700;
  background: #f5f1ea;
  border-right: 1px solid #ded7cc;
  border-bottom: 1px solid #ded7cc;
}

.day-cell {
  min-height: 120px;
  text-align: left;
  vertical-align: top;
  border: 0;
  border-right: 1px solid #ded7cc;
  border-bottom: 1px solid #ded7cc;
  background: #fff;
  padding: 0.55rem;
  cursor: pointer;
  overflow: hidden;
}

.day-cell:hover, .day-cell.selected {
  background: #fff9ed;
  box-shadow: inset 0 0 0 2px #c79755;
}

.day-cell.empty {
  background: #f8f8f8;
  cursor: default;
}

.day-number {
  display: block;
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.events {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.event {
  display: block;
  border-radius: 6px;
  padding: 0.25rem 0.35rem;
  font-size: 0.72rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #34424b;
}

.events small {
  font-size: 0.7rem;
  color: #697781;
}

.day-details {
  margin-top: 1.5rem;
  border-top: 1px solid #e2dbd2;
  padding-top: 1rem;
}

.day-details h2 {
  text-transform: capitalize;
}

.usage-card {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
  border-left: 5px solid #d7cabb;
  padding: 1rem;
  margin: 0.75rem 0;
  background: #fafafa;
  border-radius: 10px;
}

.usage-card.future {
  border-color: #6fa981;
  background: #f2faf5;
}

.usage-card.today {
  border-color: #d1a54a;
  background: #fff9e9;
}

.usage-card.cancelled {
  border-color: #b98686;
  opacity: 0.75;
}

.usage-card h3, .usage-card p {
  margin: 0.2rem 0;
}

.usage-card small {
  color: #64727b;
}

.usage-card a {
  color: #865d2d;
  white-space: nowrap;
  font-weight: 700;
}

.status {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #66747c;
}

.error {
  color: #a52b2b;
  background: #fff0f0;
  padding: 0.75rem;
  border-radius: 8px;
}

@media (max-width: 760px) {
  .page-heading {
    flex-direction: column;
  }
  .summary-grid {
    grid-template-columns: 1fr;
  }
  .weekday {
    font-size: 0.72rem;
    padding: 0.45rem 0.1rem;
  }
  .day-cell {
    min-height: 78px;
    padding: 0.3rem;
  }
  .event {
    width: 9px;
    height: 9px;
    border-radius: 50%;
    padding: 0;
    font-size: 0;
  }
  .events {
    flex-direction: row;
    flex-wrap: wrap;
  }
  .events small {
    display: none;
  }
  .usage-card {
    align-items: flex-start;
    flex-direction: column;
  }
