.booking-page {
  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.booking-shell {
  max-width: 1120px;
  margin: 0 auto;
}

.section-head {
  margin-bottom: 28px;
  max-width: 760px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1 {
  color: #08263a;
  margin: 8px 0;
}

.booking-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 18px;
}

.booking-card, .booking-detail-card, .empty-card {
  background: #fff;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
  border: 1px solid rgba(8, 38, 58, 0.08);
}

.booking-card h2 {
  margin: 12px 0 8px;
  color: #08263a;
  font-size: 1.25rem;
}

.booking-card p {
  margin: 4px 0;
  color: #516070;
}

.status-pill {
  display: inline-flex;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  padding: 6px 10px;
  font-size: 0.78rem;
  font-weight: 700;
}

.booking-meta {
  display: grid;
  gap: 6px;
  margin: 18px 0;
  color: #08263a;
}

.booking-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary {
  background: #08263a;
  color: #fff;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.muted {
  color: #667;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 14px;
  margin: 24px 0;
}

.detail-grid div {
  background: #f8f5ef;
  border-radius: 16px;
  padding: 14px;
  display: grid;
  gap: 4px;
}

.detail-grid strong {
  color: #08263a;
}

.detail-grid span {
  color: #516070;
}

.comments {
  background: #f8f5ef;
  padding: 16px;
  border-radius: 16px;
  color: #516070;
}

.paid-badge {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 0.55rem 0.9rem;
  background: #047857;
  color: #fff;
  font-weight: 700;
}

.booking-meta span {
  line-height: 1.4;
}

.booking-tabs {
  display: inline-flex;
  gap: 0.5rem;
  background: rgba(8, 38, 58, 0.06);
  border-radius: 999px;
  padding: 0.35rem;
  margin: 1rem 0;
}

.booking-tabs button {
  border: 0;
  border-radius: 999px;
  background: transparent;
  padding: 0.7rem 1.1rem;
  color: #08263a;
  font-weight: 800;
  cursor: pointer;
}

.booking-tabs button.active {
  background: #fff;
  box-shadow: 0 8px 22px rgba(8, 38, 58, 0.08);
}

.booking-tabs span {
  display: inline-flex;
  min-width: 1.6rem;
  height: 1.6rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.16);
  color: #b58b4a;
  margin-left: 0.35rem;
}

.booking-toolbar-grid {
  display: grid;
  grid-template-columns: minmax(220px, 1.4fr) repeat(4, minmax(140px, 1fr)) auto;
  gap: 0.85rem;
  align-items: end;
  margin: 1rem 0;
}

.booking-toolbar-grid label {
  display: grid;
  gap: 0.35rem;
  color: #08263a;
  font-weight: 700;
}

.booking-toolbar-grid select,
.booking-toolbar-grid input {
  min-height: 42px;
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.65rem 0.75rem;
  background: #fff;
  font: inherit;
}

@media (max-width: 980px) {
  .booking-toolbar-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 640px) {
  .booking-tabs {
    width: 100%;
  }
  .booking-tabs button {
    flex: 1;
  }
  .booking-toolbar-grid {
    grid-template-columns: 1fr;
  }
}
.status-clickable {
  border: 0;
  cursor: pointer;
  transition: transform 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
}

.status-clickable:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 18px rgba(8, 38, 58, 0.12);
}

.status-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background: rgba(8, 38, 58, 0.42);
  -webkit-backdrop-filter: blur(4px);
          backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  padding: 1rem;
}

.status-modal {
  width: min(620px, 100%);
  max-height: min(760px, 92vh);
  overflow: auto;
  background: #fff;
  border-radius: 28px;
  padding: clamp(1.25rem, 3vw, 2rem);
  box-shadow: 0 30px 80px rgba(8, 38, 58, 0.24);
  position: relative;
  border: 1px solid rgba(8, 38, 58, 0.08);
}

.status-modal h2 {
  color: #08263a;
  margin: 0.35rem 0 0.5rem;
}

.status-modal p {
  color: #516070;
  line-height: 1.6;
}

.modal-close {
  position: absolute;
  top: 0.9rem;
  right: 0.9rem;
  width: 38px;
  height: 38px;
  border: 0;
  border-radius: 999px;
  background: #f8f5ef;
  color: #08263a;
  font-size: 1.4rem;
  cursor: pointer;
}

.status-timeline {
  display: grid;
  gap: 0.75rem;
  margin: 1.25rem 0;
}

.status-step {
  display: grid;
  grid-template-columns: 170px 1fr;
  gap: 0.8rem;
  align-items: center;
  padding: 0.95rem;
  border-radius: 18px;
  border: 1px solid rgba(8, 38, 58, 0.08);
  background: #f8f5ef;
}

.status-step strong {
  color: #08263a;
}

.status-step span {
  color: #516070;
  line-height: 1.45;
}

.status-step.done {
  background: rgba(4, 120, 87, 0.09);
  border-color: rgba(4, 120, 87, 0.18);
}

.status-step.done strong::before {
  content: "✓ ";
  color: #047857;
}

.status-step.pending {
  background: rgba(181, 139, 74, 0.09);
  border-color: rgba(181, 139, 74, 0.18);
}

.status-step.pending strong::before {
  content: "• ";
  color: #b58b4a;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  margin-top: 1rem;
}

@media (max-width: 560px) {
  .status-step {
    grid-template-columns: 1fr;
  }
  .modal-actions {
    justify-content: stretch;
  }
  .modal-actions .btn {
    flex: 1;
  }
}
/* Cleaner aligned booking list */
.bookings-list {
  display: grid;
  gap: 0.75rem;
  margin-top: 1rem;
}

.booking-list-row {
  display: grid;
  grid-template-columns: 150px minmax(190px, 1.2fr) minmax(190px, 1.1fr) 120px minmax(170px, auto);
  gap: 1rem;
  align-items: center;
  width: 100%;
  text-align: left;
  border: 1px solid rgba(8, 38, 58, 0.08);
  border-radius: 22px;
  background: #fff;
  padding: 1rem;
  box-shadow: 0 14px 35px rgba(8, 38, 58, 0.07);
  cursor: pointer;
}

.booking-list-row:hover {
  transform: translateY(-1px);
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.11);
}

.booking-main,
.booking-customer,
.booking-price,
.row-actions {
  min-width: 0;
}

.booking-main,
.booking-customer,
.booking-price {
  display: grid;
  gap: 0.2rem;
}

.booking-main strong,
.booking-customer strong,
.booking-price strong {
  color: #08263a;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.booking-main small,
.booking-customer small,
.booking-price small {
  color: #516070;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.booking-price {
  text-align: right;
}

.row-actions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 0.45rem;
  flex-wrap: wrap;
}

.mini-btn {
  border: 0;
  border-radius: 999px;
  padding: 0.55rem 0.85rem;
  background: #08263a;
  color: #fff;
  font-weight: 800;
  cursor: pointer;
}

.row-chevron {
  color: #b58b4a;
  font-weight: 900;
  font-size: 1.35rem;
}

@media (max-width: 980px) {
  .booking-list-row {
    grid-template-columns: 1fr;
    align-items: start;
  }
  .booking-price {
    text-align: left;
  }
  .row-actions {
    justify-content: flex-start;
  }
}
.bookings-page-head {
  max-width: none;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.bookings-page-head > div {
  max-width: 760px;
}

.create-booking-btn {
  white-space: nowrap;
  background: #ff8a1d;
  color: #fff;
  box-shadow: 0 12px 26px rgba(255, 138, 29, 0.22);
}

.create-booking-btn:hover {
  transform: translateY(-1px);
}

@media (max-width: 720px) {
  .bookings-page-head {
    flex-direction: column;
  }
  .create-booking-btn {
    width: 100%;
    justify-content: center;
  }
}
/* Release 85 premium booking cards */
.booking-main {
  display: flex !important;
  align-items: center;
  gap: 0.75rem;
}

.booking-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, #e8f4f7, #f8f5ef);
  font-size: 1.35rem;
  flex: 0 0 auto;
}

.booking-progress {
  display: block;
  width: 100%;
  height: 6px;
  border-radius: 999px;
  background: rgba(8, 38, 58, 0.1);
  overflow: hidden;
  margin-top: 0.35rem;
}

.booking-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #0b6e8f, #f28c28);
}

.booking-list-row {
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

@media (max-width: 980px) {
  .booking-list-row {
    padding: 1.15rem;
  }
  .booking-price {
    width: 100%;
  }
